import { useState } from 'react'
import type { MobileDestination } from '@ds-mo/ui/shell'
import { DsBarNav, DsBarTitle, DsMobileBarNav, DsMobileHeader, DsMobileSheetNav, DsPanelNav, DsShellApp, DsShellPage, DsShellTools } from '@ds-mo/ui/react'

export function AppShell() {
  const [destination, setDestination] = useState<MobileDestination>('area')
  const [sheetNavOpen, setSheetNavOpen] = useState(false)
  return (
    <DsShellApp mobileDestination={destination} mobileSheetNavOpen={sheetNavOpen}>
      <DsPanelNav slot="panel" />
      <DsMobileSheetNav slot="mobile-sheet-nav" open={sheetNavOpen} />
      <DsBarNav slot="bar" />
      <DsShellTools slot="tools"><div slot="search-view">Search</div></DsShellTools>
      <DsShellPage responsiveMode="mobile"><DsBarTitle slot="header" heading="Live Map" /><DsMobileHeader slot="mobile-header" heading="Live Map" /><main>{/* routed workspace */}</main></DsShellPage>
      <DsMobileBarNav slot="mobile-bar-nav" activeDestination={destination} sheetNavExpanded={sheetNavOpen} onDsSheetNavToggle={event => setSheetNavOpen(event.detail)} onDsDestinationChange={event => { setSheetNavOpen(false); setDestination(event.detail.destination) }} />
    </DsShellApp>
  )
}
